"""Author the private Chapter 3 companion from its saved extraction, without API calls.
Output is an additive curated_series payload; no original approval/progress is replaced.
"""
import json, math, sys, subprocess
from pathlib import Path
SOURCE=json.loads(Path(sys.argv[1]).read_text())
LESSONS=[]
CURRENT=[]
serial=0

def mc(prompt, answer, wrong, why):
 global serial
 options=[str(answer)]+[str(x) for x in wrong]
 shift=serial%len(options);serial+=1
 options=options[shift:]+options[:shift]
 return dict(type='choice',prompt=prompt,answer=str(answer),choices=options,correct=options.index(str(answer)),explanation=why,source_ids=CURRENT.copy())
def number(prompt, answer, unit, why):
 return dict(type='number',prompt=prompt,answer=f'{answer:g} {unit}'.strip(),choices=[],correct=-1,explanation=why,source_ids=CURRENT.copy())
def pick(title,prompt,answer,wrong,why):
 q=mc(prompt,answer,wrong,why)
 return dict(kind='choice',title=title,prompt=prompt,expected=q['answer'],choices=q['choices'],correct=q['correct'],simulator='none',explanation=why,source_ids=CURRENT.copy())
def sim(title,template,prompt,expected,why):
 return dict(kind='simulation',title=title,prompt=prompt,expected=expected,choices=[],correct=-1,simulator=template,explanation=why,source_ids=CURRENT.copy())
def begin(*ids):
 global CURRENT
 CURRENT=list(ids)
def section(title,body):return dict(heading=title,body=body,source_ids=CURRENT.copy())
def add(title,description,goals,sections,questions,activities,caution='These are paper calculations and idealized simulations, not instructions to build or energize a circuit.',figure='units'):
 i=len(LESSONS)+1;identifier=f'C3-CURATED-U{i:02}'
 for j,q in enumerate(questions,1):q['id']=f'{identifier}-Q{j:02}'
 LESSONS.append(dict(id=identifier,curated=True,kind='math',destination='source',dashboard_track='ceta',curriculum=dict(section='exam',source_id='associate-cet',source_title='Associate CET Study Guide',chapter_id='3',chapter_title='Basic Math used in Electronic Service & Decibels',order=i,dashboard=True),dashboard_ready=True,ordering='independent',prerequisites=[],title=title,description=description,objectives=goals,sections=sections,questions=questions,activities=activities,review_lessons=[],plan=dict(id=f'U{i:02}',title=title,kind='math',destination='source',ordering='independent',prerequisites=[],source_ids=CURRENT.copy()),overview=dict(eyebrow='CHAPTER 3 · GUIDED MATHEMATICS',hint='A problem to investigate',mission=questions[0]['prompt'],reveal=questions[0]['explanation'],anchors=[[f'Goal {j+1}',g] for j,g in enumerate(goals[:3])],missionType=figure,outcome=description,caution=caution),technical_review=dict(ready=True,summary='Authored and checked in this Work session against saved Chapter 3 evidence and deterministic calculations. No paid independent review or fresh image inspection is claimed.',findings=[dict(severity='note',description=caution,source_id=','.join(CURRENT))])))

begin('S1','S2')
add('01 · Read the scale before calculating','Use powers of ten and prefixes to keep the same electrical quantity while changing its written scale.',
 ['Explain what a positive or negative exponent does','Convert between prefixes using their factors','Check whether a converted value is sensible'],[
 section('A prefix changes the label, not the quantity','Think of 1,000 milliamperes and 1 ampere as two labels for the same current. The prefix tells you the scale used by the number beside it. Kilo means 10³, milli means 10⁻³, micro means 10⁻⁶, and pico means 10⁻¹².\n\nBefore entering a value into a formula, read the complete label. A value of 5 mA is not the same as 5 A. Convert the number and its unit together: 5 mA = 5 × 10⁻³ A = 0.005 A. The current has not become smaller; you have expressed it in a larger unit.'),
 section('Why scientific notation helps','Scientific notation separates a manageable leading number from a scale factor. In 1.25 × 10⁵, the 10⁵ multiplies 1.25 by 100,000, giving 125,000. A negative exponent means a reciprocal: 10⁻³ = 1/1,000. So 7 × 10⁻³ is 0.007.\n\nKeep the leading number between 1 and 10 when writing normalized scientific notation. If you move the decimal in the leading number, compensate with the exponent so the original value stays unchanged. This is a way to organize place value, not permission to drop zeros arbitrarily.'),
 section('A worked conversion: pF to µF','The source example starts with 1,000 pF. Convert to farads first: 1,000 × 10⁻¹² F = 10⁻⁹ F. One microfarad is 10⁻⁶ F, so the number of microfarads is 10⁻⁹ / 10⁻⁶ = 10⁻³. The result is 0.001 µF.\n\nAn equivalent shortcut divides the picofarad number by one million. That million comes from the six powers of ten between pico and micro. In the slider, compare several pF values and watch both µF and F update. Explain the factor before trusting a decimal shift.'),
 section('Check direction and capitalization','Moving from a smaller unit to a larger unit produces a smaller written number. Thus 700 kHz is 700,000 Hz but only 0.7 MHz. The frequency itself remains identical. A conversion that makes all three numbers equal has ignored the prefixes.\n\nCase matters: m is milli and M is mega. A sensible result includes its unit, and a quick conversion back should recover the original number. Use these two checks whenever an electronics answer seems a thousand or a million times too large.')],
 [mc('What does 10⁻³ mean?','One thousandth',['One thousand','Negative three','Minus one thousand'],'A negative exponent gives a reciprocal: 10⁻³ = 1/10³ = 0.001.'),
 mc('Which is normalized scientific notation for 125,000?','1.25 × 10⁵',['12.5 × 10⁵','1.25 × 10⁻⁵','125 × 10⁵'],'1.25 × 100,000 = 125,000, with the leading number between 1 and 10.'),
 mc('Which current equals 5 mA?','0.005 A',['5,000 A','0.5 A','5 A'],'Milli means 10⁻³: 5 × 0.001 A = 0.005 A.'),
 mc('Which frequency equals 700 kHz?','0.7 MHz',['700 MHz','7 MHz','0.0007 MHz'],'1 MHz is 1,000 kHz, so divide 700 by 1,000.'),
 mc('Convert 1,000 pF to µF.','0.001 µF',['1 µF','1,000 µF','0.000001 µF'],'Pico-to-micro is a millionfold scale change; divide 1,000 by 1,000,000.'),
 mc('Someone replaces 3 mA with 3 A in a formula. What happened?','The represented current became 1,000 times too large',['The value stayed equivalent','The current became 1,000 times smaller','Only the spelling changed'],'Removing milli without adjusting the number multiplies the represented current by 1,000.'),
 number('Express 2.4 kHz in hertz. Enter the number in Hz.',2400,'Hz','Kilo means 1,000; 2.4 × 1,000 = 2,400 Hz.'),
 mc('Which statement about m and M is correct?','m is milli; M is mega',['Both mean milli','Both mean mega','m is micro; M is milli'],'Prefix capitalization changes the factor, so it is part of the measurement.')],
 [sim('Move between capacitance scales','prefixes','Start at 1,000 pF, then increase the slider to 2,000 pF. Predict the µF values before moving it.','0.001 µF becomes 0.002 µF','The number doubles at every equivalent scale; pF-to-µF divides by one million.'),pick('Spot the thousandfold mistake','Which pair represents one unchanged current?','2 mA and 0.002 A',['2 mA and 2 A','2 mA and 2,000 A','2 mA and 0.2 A'],'Changing from mA to A requires multiplying by 10⁻³, not simply removing the prefix.')])

begin('S3','S4')
add('02 · Rearrange equations without guessing','Use inverse operations on both sides of an equality, then check the result by substitution.',
 ['Interpret equality as a balance','Isolate a variable using an inverse operation','Test the result in the original equation'],[
 section('Equality is a relationship to preserve','The equals sign says the expression on the left has the same value as the expression on the right. A letter is a name for a quantity; it can stand for a known number or an unknown you need to find. In 4y = 2, the term 4y means four times y.\n\nYou cannot remove the 4 from one side and leave the other side untouched. Whatever operation you choose must preserve the relationship. Divide both sides by the same nonzero number to undo multiplication, or multiply both sides to undo a division.'),
 section('Solve one small problem completely','Start with 4y = 2. Divide both sides by 4: (4y)/4 = 2/4. The left simplifies to y because 4/4 = 1. The right is 0.5, so y = 0.5. Check in the original equation: 4 × 0.5 = 2.\n\nThat check matters. An answer of y = 8 might look like a simple multiplication, but 4 × 8 = 32 does not reproduce the original right side. The substitution test diagnoses the mistake without needing to remember an algebra shortcut.'),
 section('Turn a product into a quotient','In a = bc, suppose you need b. Because b is multiplied by c, divide both sides by c: a/c = bc/c = b, assuming c is nonzero. So b = a/c. If you need c instead, divide both sides by b to get c = a/b.\n\nThis same reasoning makes Ohm’s law useful. From V = IR, divide by R to get I = V/R, or divide by I to get R = V/I. The unknown tells you which form is convenient; the underlying relationship does not change.'),
 section('Numbers, units and a final check','For a hypothetical V = 12 V and R = 3 kΩ, first write R = 3,000 Ω. Then I = 12/3,000 = 0.004 A. Check by multiplying: 0.004 A × 3,000 Ω = 12 V.\n\nUse the algebra slider to change the coefficient and right-hand side. A larger coefficient with the same right side makes the unknown smaller. That directional prediction is another error check. Do not divide by zero; it changes the mathematical conditions under which the rearrangement is valid.')],
 [mc('In 4y = 2, what does 4y mean?','4 multiplied by y',['4 plus y','4 divided by y','The digits 4 and y joined together'],'A coefficient next to a variable denotes multiplication.'),
 mc('What operation isolates y in 4y = 2?','Divide both sides by 4',['Multiply only the right side by 4','Subtract y from both sides','Divide both sides by y'],'Dividing by the nonzero coefficient undoes multiplication by 4.'),
 mc('What is y in 4y = 2?','0.5',['8','2','4'],'y = 2/4 = 0.5, and 4 × 0.5 returns 2.'),
 mc('From a = bc, how do you isolate b when c is nonzero?','b = a/c',['b = ac','b = c/a','b = a − c'],'Divide both sides by c to remove c from the product.'),
 mc('Which check tests an answer to 4y = 2 directly?','Substitute it into 4y and see whether the result is 2',['Check whether y is an integer','Multiply it by 2','Check whether it is positive only'],'The original equality is the test the solution must satisfy.'),
 mc('If 6x = 18, which value works?','3',['108','12','1/3'],'Divide by 6, then check 6 × 3 = 18.'),
 mc('With a fixed right side, doubling the coefficient in by = a makes y…','Half as large',['Twice as large','Unchanged','Automatically negative'],'y = a/b, so doubling the denominator halves the quotient.'),
 number('Solve 5x = 20. Enter x.',4,'','x = 20/5 = 4; substitution gives 5 × 4 = 20.'),
 mc('Which condition matters when dividing both sides by c?','c must not be zero',['c must equal one','c must be an integer','c must be negative'],'Division by zero is undefined; the quotient rearrangement requires a nonzero divisor.')],
 [sim('Balance the equation','algebra','Set the coefficient to 4 and the right side to 2. Then keep the right side fixed and set the coefficient to 8.','The unknown changes from 0.5 to 0.25','The unknown equals the right-hand side divided by the coefficient.'),pick('Select the inverse operation','In V = IR, you want I and know a nonzero R. What should you do?','Divide both sides by R',['Multiply both sides by R','Subtract R from V','Divide only the right side by I'],'Dividing by R leaves I alone and gives I = V/R.')])

begin('S18','S8','S10')
add('03 · Tell a symbol from a unit','Read formulas as relationships between quantities, using the symbol and unit tables as a reference rather than a memory test.',
 ['Separate a variable name from its measurement unit','Recognize common electronic and Greek notation','Resolve a symbol’s meaning from context'],[
 section('A letter and a unit do different jobs','In I = V/R, I names current, while amperes are the unit used to express its value. R names resistance, while Ω is its unit symbol. The source table similarly places resistance, reactance and impedance in ohms. These are different quantities even though they share a unit.\n\nBefore calculating, say what each symbol means and what unit the numerical value uses. A line such as R = 2 kΩ is a useful complete statement: it identifies the quantity, its value and its scale.'),
 section('The same character can have different meanings','Context decides meaning. C in Q = CV means capacitance, measured in farads. C after a charge value is the abbreviation for coulomb. For example, Q = 60 µC gives a charge, not a capacitance. Likewise, F can be the farad unit while some source notation uses capital F for frequency.\n\nAvoid guessing from the shape of a letter. Read the local definition and the surrounding units. We use f for frequency and E for energy where defined, and keep V for voltage in the capacitor energy equation so the roles stay distinct.'),
 section('Greek letters are readable labels','The chapter includes a Greek-letter reference table. μ is mu and appears in the micro-prefix. Ω is uppercase omega and is used for the ohm unit. π is pi and appears in reactance and resonance formulas. You can look these up; recognizing them is more valuable here than reciting the entire alphabet.\n\nA symbol in a formula is not automatically a measurement unit. In X_C = 1/(2πfC), π is a dimensionless numerical constant, f is frequency and C is capacitance. The result X_C has the unit ohm.'),
 section('Use units as a reasonableness test','A capacitor charge calculation should end in coulombs; an energy calculation should end in joules; a frequency calculation should end in hertz. If you report 60 µF for a question asking for stored charge, the unit alone reveals a category mistake.\n\nThe table also names siemens for conductance, admittance and susceptance. Recognize that unit association, but do not infer formulas for those quantities from this chapter’s table alone. A reference table is a vocabulary aid, not proof that an unseen topic has been taught.')],
 [mc('In R = 2 kΩ, what does R name?','Resistance',['The kilo-prefix','The ohm unit itself','Resonant frequency'],'R is the variable naming the quantity; kΩ describes the unit scale.'),
 mc('Which quantities use ohms in the chapter’s units table?','Resistance, reactance and impedance',['Charge, energy and time','Capacitance and frequency','Power and current'],'A shared unit does not make these three quantities interchangeable.'),
 mc('In Q = CV, what does C mean?','Capacitance',['Coulomb as a numerical constant','Current','A fixed conversion factor'],'Here C names capacitance, while Q is charge and V is voltage.'),
 mc('In Q = 60 µC, what does the final C mean?','Coulomb',['Capacitance','Current','Centimeter'],'C is the unit abbreviation in this value, not the variable from Q = CV.'),
 mc('What is μ in an electronic prefix called?','Mu',['Omega','Pi','Lambda'],'The lower-case Greek letter mu is used for micro, or 10⁻⁶.'),
 mc('Which unit belongs to energy?','Joule',['Farad','Hertz','Ohm'],'Energy is expressed in joules; stored capacitor charge uses coulombs.'),
 mc('Which unit does the chapter associate with conductance?','Siemens',['Volt','Farad','Watt'],'The table identifies siemens; it does not supply a full conductance lesson by itself.'),
 mc('How should you interpret an unfamiliar symbol in a formula?','Read its local definition and check the units',['Assume it means the same thing in every formula','Treat every capital letter as a unit','Ignore it if a calculator accepts the number'],'Local definitions and units establish meaning; letters can be reused in different contexts.')],
 [pick('Sort the quantity','A result labeled 25 µJ represents what?','Energy',['Charge','Capacitance','Frequency'],'J is joule. The micro-prefix changes the scale but not the kind of quantity.'),pick('Decode the formula','In X_C = 1/(2πfC), which entry is a dimensionless constant?','π',['f','C','X_C'],'Pi is a number; the other entries represent frequency, capacitance and reactance.')])

begin('S4','S5')
add('04 · Choose the right circuit equation','Calculate voltage, current, resistance and resistive power by matching the equation to the quantities you actually know.',
 ['Choose a useful form of Ohm’s law','Convert values before substituting','Distinguish electrical power from voltage or current'],[
 section('Start with the quantity you need','Ohm’s law is V = IR. Voltage V is measured in volts, current I in amperes and resistance R in ohms. If you know any two, choose a form that isolates the third: I = V/R or R = V/I.\n\nRead the circuit description before selecting numbers. The voltage must be across the resistor whose resistance you use. A supply label and an unrelated resistor elsewhere on a board are not automatically a valid pair. Our examples use ideal single resistive loads, so the relationship is clear.'),
 section('A complete current calculation','For a hypothetical 12 V across 3 kΩ, write the resistance as 3,000 Ω. Substitute I = 12/3,000 = 0.004 A. Multiply by 1,000 to express this as 4 mA. Check the result: 0.004 × 3,000 = 12 V.\n\nPredict before calculating. Increasing voltage at fixed resistance increases current; increasing resistance at fixed voltage decreases current. A result that rises when only resistance doubles needs investigation. The Ohm’s-law slider makes these two relationships visible.'),
 section('Power describes an energy-transfer rate','Power P is measured in watts. For the resistive cases here, P = IV. With 12 V and 0.004 A, P = 0.048 W, or 48 mW. Voltage is energy per charge and current is charge per time; their product gives energy per time.\n\nThe chapter also gives P = I²R and P = V²/R. Choose the version that uses the values already known. With the same 12 V and 3,000 Ω, P = 12²/3,000 = 144/3,000 = 0.048 W. Agreement between two methods is a useful check.'),
 section('Why squares change the prediction','At fixed R, power varies as V². Doubling voltage doubles current but quadruples power. At fixed current, doubling R doubles I²R power; at fixed voltage, doubling R halves V²/R power. Those different conclusions come from different quantities being held constant.\n\nAlways state what stays fixed. Use the power widget to explore this before answering a scenario. Do not interpret a calculated wattage as permission to exceed an actual component’s rating; these are idealized numerical models.'),
 section('Use the accepted formulas, not a doubtful rearrangement','The saved scan review flags ambiguous prose rearrangements on p. 18. This lesson uses the accepted V = IR, P = IV, P = I²R and P = V²/R relationships. It does not treat a poorly delimited radical in the source as a new rule.\n\nWork in this order: name the unknown, list known quantities and units, convert prefixes, select an equation, substitute with units, calculate, then check direction and scale. The sequence is more dependable than hunting through a formula wheel without understanding what its letters mean.')],
 [mc('You know V and R and want I. Which relation is direct?','I = V/R',['I = VR','I = R/V','I = V + R'],'Dividing V = IR by R isolates current.'),
 mc('What current flows through 3 kΩ with 12 V across it?','4 mA',['4 A','0.004 mA','36 mA'],'12/3,000 = 0.004 A = 4 mA.'),
 mc('A fixed resistor’s voltage doubles. Its current…','Doubles',['Halves','Quadruples','Stays unchanged'],'I = V/R is directly proportional to voltage at fixed R.'),
 mc('At fixed voltage, doubling resistance makes current…','Half as large',['Twice as large','Four times as large','Unchanged'],'Resistance is the denominator in I = V/R.'),
 mc('What unit belongs to P in P = IV?','Watt',['Volt','Ampere','Coulomb'],'Power is an energy-transfer rate, measured in watts.'),
 mc('A 5 V resistive load draws 5 mA. What power is transferred?','25 mW',['25 W','1 mW','0.025 mW'],'Convert 5 mA to 0.005 A; 5 × 0.005 = 0.025 W = 25 mW.'),
 mc('You know only V and R. Which power formula uses them directly?','P = V²/R',['P = IR²','P = I/R','P = VR'],'Substitute I = V/R into P = IV to obtain V²/R.'),
 mc('At fixed resistance, doubling voltage makes resistive power…','Four times as large',['Twice as large','Half as large','Unchanged'],'The voltage is squared in P = V²/R.'),
 mc('Why does entering 4 for a current of 4 mA give a wrong wattage?','The formula then uses 4 A, a thousandfold scale error',['The formula requires milliamperes only','Milliamperes are always negative','Power cannot be calculated from current'],'P = IV uses amperes with volts when the result is watts.'),
 mc('Which result cross-checks 12 V across 3 kΩ?','4 mA and 48 mW',['4 mA and 48 W','4 A and 48 mW','0.4 mA and 480 mW'],'Current is 0.004 A, and its product with 12 V is 0.048 W.'),
 number('A 2 kΩ resistor carries 3 mA. Enter its voltage in V.',6,'V','V = 0.003 A × 2,000 Ω = 6 V.'),
 mc('A question holds current fixed while resistance doubles. Using I²R, power…','Doubles',['Halves','Quadruples','Cannot change'],'At fixed I, the squared current factor is constant and P scales directly with R.'),
 mc('Which step should precede substitution?','Convert the known values to compatible units',['Remove unit labels','Round every value to an integer','Choose the largest number'],'Compatible units prevent prefix errors and help interpret the result.'),
 number('An ideal 10 V is across 1 kΩ. Enter resistive power in mW.',100,'mW','P = 10²/1,000 = 0.1 W = 100 mW.')],
 [sim('Separate voltage and resistance effects','ohm','Keep resistance at 1,000 Ω. Move voltage from 5 V to 10 V, then keep voltage fixed and double resistance.','Current doubles with voltage and halves with resistance','Only one changed variable lets you identify the direct or inverse relationship.'),sim('See the squared effect','power','At 1,000 Ω, compare 5 V and 10 V. Predict the power ratio before moving the voltage control.','Power rises from 25 mW to 100 mW','V²/R contains a square, so a twofold voltage change gives a fourfold power change.'),pick('Choose what stays fixed','Which statement correctly includes the condition for a fourfold power increase?','Double voltage at fixed resistance',['Double resistance at fixed voltage','Double current at fixed voltage','Double resistance at fixed current'],'The condition is essential; P = V²/R gives a fourfold change only when R stays fixed.')])

begin('S9','S4')
add('05 · Combine resistor paths','Identify series versus parallel before choosing the arithmetic, and test the result against physical path reasoning.',
 ['Add resistances in one series path','Use reciprocal addition for parallel paths','Apply magnitude checks to catch network mistakes'],[
 section('One path or several branches?','Series resistors lie in one path, so their resistances add. If the values are 1 kΩ and 2 kΩ, the total is 3 kΩ. Parallel resistors provide separate paths between the same two nodes. Their equivalent resistance is found by adding reciprocal resistances and taking the reciprocal of that sum.\n\nThe circuit arrangement chooses the rule. The fact that a page lists several resistor values does not tell you whether to add them directly. First identify how the paths connect.'),
 section('Work a parallel example slowly','For 6 Ω in parallel with 3 Ω, start with 1/R_T = 1/6 + 1/3. Use a common denominator: 1/6 + 2/6 = 3/6 = 1/2. That sum has units of inverse ohms. Take its reciprocal to obtain R_T = 2 Ω.\n\nFor two positive resistors, you can also use R_T = R₁R₂/(R₁ + R₂). Here 6 × 3/(6 + 3) = 18/9 = 2 Ω. The shortcut is for two branches, not a rule to multiply every resistor in a larger network.'),
 section('Equal branches provide a useful shortcut','For n equal resistors of resistance R, the parallel total is R/n. Three 1 kΩ branches therefore have an equivalent of 1,000/3 ≈ 333.3 Ω. At an ideal 5 V, each branch carries 5 mA and the total is 15 mA. The same total follows from 5/333.3 ≈ 0.015 A.\n\nR/n assumes equal values. If the branches are unequal, use the reciprocal rule rather than averaging their resistances or dividing an arbitrary branch by the number of branches.'),
 section('Magnitude checks and changing one branch','A positive series total is larger than any of its individual resistors. A parallel equivalent with at least two positive finite branches is smaller than the smallest branch. The 2 Ω result for 6 Ω and 3 Ω passes that check; 9 Ω would not.\n\nIn the widget, hold R₂ fixed and increase R₁. The parallel equivalent increases because that branch provides less conductance, but it stays below R₂. Adding another positive parallel branch reduces the total resistance. These checks often find a wrong formula faster than repeating the arithmetic.')],
 [mc('Two resistors share one series path. What combines directly?','Their resistances',['Their reciprocal resistances only','Their voltages regardless of current','Their products'],'Series total resistance is the sum of individual resistances.'),
 mc('What is 1 kΩ plus 2 kΩ in series?','3 kΩ',['0.667 kΩ','2 kΩ','0.5 kΩ'],'Add values expressed in the same unit.'),
 mc('What is 6 Ω in parallel with 3 Ω?','2 Ω',['9 Ω','3 Ω','18 Ω'],'The reciprocal sum is 1/2 Ω⁻¹, whose reciprocal is 2 Ω.'),
 mc('What does 1/R₁ + 1/R₂ represent before taking the reciprocal?','A sum with units of inverse ohms',['The final resistance in ohms','A current in amperes','A voltage in volts'],'The reciprocal step is necessary to return to a resistance.'),
 mc('Three equal 1 kΩ resistors in parallel have a total near…','333 Ω',['3,000 Ω','1,000 Ω','3 Ω'],'The equal-branch shortcut gives 1,000/3 Ω.'),
 mc('Which magnitude check fits two positive resistors in parallel?','The total is below the smaller resistor',['The total exceeds their sum','The total is their average','The total equals the larger one exactly'],'An extra conducting path reduces the equivalent resistance.'),
 mc('Which shortcut is specifically for two parallel resistors?','R₁R₂/(R₁ + R₂)',['R₁ + R₂','R₁/R₂','R₁R₂'],'It is the algebraic simplification of a two-term reciprocal sum.'),
 mc('When may R/n be used for parallel branches?','When all n resistors have the same resistance',['For any unequal resistor list','Only for two unequal values','Only when the total is zero'],'The equality of branch values is part of the shortcut’s assumption.'),
 mc('Adding another finite positive parallel branch generally makes equivalent resistance…','Smaller',['Larger','Unchanged','Negative'],'The reciprocal sum increases, so its reciprocal decreases.'),
 number('Enter the series total of 2 kΩ, 3 kΩ and 5 kΩ in kΩ.',10,'kΩ','Series values add: 2 + 3 + 5 = 10 kΩ.'),
 mc('With an ideal 5 V on three 1 kΩ parallel branches, total current is…','15 mA',['5 mA','1.67 mA','15 A'],'Each branch carries 5 mA and the source current is their sum.'),
 mc('A calculated parallel total for 1 kΩ and 2 kΩ is 3 kΩ. What most likely happened?','The series rule was used instead',['The reciprocal rule produced the correct result','The total was rounded appropriately','Equal-branch division was used correctly'],'3 kΩ is the series sum; the parallel equivalent should be below 1 kΩ.')],
 [sim('Compare two arrangements','network','At R₁ = 1,000 Ω and R₂ = 2,000 Ω, compare both totals. Increase R₁ while holding R₂ fixed.','The series total is 3,000 Ω and the parallel total is about 666.7 Ω initially','The same component values produce different equivalent resistance because their paths differ.'),pick('Choose the path rule','Two resistor branches join the same pair of nodes. Which calculation fits?','Add reciprocal resistances, then take the reciprocal',['Add the resistances directly','Subtract the smaller resistance','Multiply without dividing'],'Parallel paths share endpoints; their conductance contributions add.')],figure='circuit')

begin('S6','S4','S9')
add('06 · Explain a battery’s voltage sag','Distinguish internal EMF from loaded terminal voltage with a simple series-resistance model.',
 ['Include internal resistance in the current path','Calculate an internal voltage drop','Explain why loaded terminal voltage is below EMF'],[
 section('The model has two resistances','EMF is the source voltage in the battery model. Internal resistance r is placed in series with the external load R. The current must pass through both, so the total resistance is R + r.\n\nThat makes I = EMF/(R + r). Do not use only R unless you are intentionally using an ideal source model with negligible internal resistance. The two models answer different questions; neither lets you infer a real battery’s internal resistance from its label alone.'),
 section('Work a complete hypothetical example','Let EMF = 6 V, the load be 5 Ω, and internal resistance be 1 Ω. Total resistance is 6 Ω, giving I = 6/6 = 1 A. The internal drop is Ir = 1 × 1 = 1 V. The voltage across the load is IR = 1 × 5 = 5 V.\n\nThe voltages add: 1 V inside the model plus 5 V at its terminals equals the 6 V EMF. You can also obtain terminal voltage as EMF − Ir. Using both routes checks that the same current and resistances were used consistently.'),
 section('Connect the numbers to sag','Terminal voltage is the voltage available across the external load. For positive internal resistance and nonzero load current, it is less than EMF. If the load resistance becomes very large, current becomes small and the internal drop becomes small.\n\nDecrease the load resistance in the widget. The current increases, so the internal voltage drop grows. Terminal voltage falls even though the model’s EMF setting has not changed. This is a model of load-dependent sag, not a command to short or heavily load a real battery.'),
 section('Keep a source example and a teaching model separate','The saved source example gives I = 1.5 V/6.25 Ω = 0.24 A, or 240 mA. That denominator includes the external and internal series resistances. Our 6 V example uses different explicitly hypothetical values to make the separate drops easy to see.\n\nAlways identify whether a voltage is EMF or terminal voltage. Reporting the 6 V setting as a measured loaded terminal voltage in our example would ignore the 1 V internal drop. A calculation does not establish safe real-battery ratings or a test method.')],
 [mc('Where does internal resistance sit in this battery model?','In series with the external load',['In parallel with the voltmeter only','Outside the current path','As a second voltage source'],'The load current passes through both external and internal resistance.'),
 mc('Which denominator belongs in the modeled current equation?','R_load + r_internal',['R_load only in every case','R_load − r_internal','R_load × r_internal'],'Series resistances add before dividing EMF by total resistance.'),
 mc('For 6 V EMF, 5 Ω load and 1 Ω internal resistance, current is…','1 A',['1.2 A','6 A','0.167 A'],'Total resistance is 6 Ω; 6 V/6 Ω = 1 A.'),
 mc('For that example, loaded terminal voltage is…','5 V',['6 V','1 V','7 V'],'The internal drop is 1 A × 1 Ω = 1 V, leaving 5 V at the load.'),
 mc('With positive internal resistance, increased current makes the internal drop…','Larger',['Smaller','Always zero','Independent of current'],'The internal voltage drop is Ir.'),
 mc('Why can a lightly loaded terminal voltage approach EMF?','Small current gives a small internal drop',['The load becomes a second battery','Internal resistance becomes negative','EMF must always be zero'],'As current tends toward zero, Ir tends toward zero.'),
 number('Calculate 1.5 V/6.25 Ω and enter current in mA.',240,'mA','The quotient is 0.24 A; multiplying by 1,000 gives 240 mA.'),
 mc('Which pair is consistent in the 6 V example?','1 V internal drop plus 5 V load drop',['1 V internal drop plus 6 V load drop','5 V internal drop plus 5 V load drop','6 V internal drop plus 6 V load drop'],'The two series drops must sum to the EMF.'),
 mc('What does the numerical model establish about a real battery’s safe short-circuit test?','Nothing; it is not a safe-test procedure',['That shorting it is safe','That all batteries have 1 Ω internal resistance','That the label gives exact loaded voltage'],'The source extraction supplies a calculation model, not equipment ratings or a laboratory procedure.')],
 [sim('Watch the loaded voltage','internal','Set EMF = 6 V, load = 5 Ω and internal resistance = 1 Ω. Then raise internal resistance while leaving the other settings fixed.','Current and terminal voltage fall','The increasing total resistance lowers current, and a greater fraction of EMF is lost internally.'),pick('Locate the missing volt','In the 6 V model, the load reads 5 V. Where is the other volt?','Across the modeled internal resistance',['Destroyed by the equals sign','Across an imaginary parallel load','Not present in the model'],'Series voltage drops account for the EMF: 1 V internally and 5 V externally.')],caution='Virtual battery models do not authorize shorting or testing a real battery. Actual source, fuse and component ratings are not supplied here.',figure='circuit')

begin('S7')
add('07 · Read a sine wave’s amplitudes','Separate signed instantaneous voltage from peak, peak-to-peak and sinusoidal RMS values.',
 ['Locate a sine wave’s positive and negative extrema','Convert peak and peak-to-peak values','Apply RMS conversion only to a sine wave'],[
 section('One cycle includes both polarities','A sine wave goes through a repeating cycle. The source figure shows 0° through 360°, with a positive extreme at 90° and a negative extreme at 270°. A negative instantaneous voltage is a signed value relative to the chosen reference; it is not a negative amplitude magnitude.\n\nIf a centered sine wave reaches +10 V and −10 V, its peak magnitude is 10 V. The distance from its lowest to highest voltage is 20 V, which is its peak-to-peak value.'),
 section('Peak and peak-to-peak answer different questions','For the centered sine wave in this lesson, V_pp = 2V_p. A 6 V peak corresponds to 12 V peak-to-peak. Going the other direction divides by two: a 24 V peak-to-peak sine wave has a 12 V peak.\n\nRead the amplitude label before entering a number into another equation. Calling a 20 V peak-to-peak value a 20 V peak value makes the assumed amplitude twice too large. The waveform widget shows the positive and negative extremes together.'),
 section('What the RMS conversion means here','For an ideal sinusoid, V_rms = V_p/√2, approximately 0.707V_p. Conversely, V_p = √2V_rms, approximately 1.414V_rms. A 10 V peak sine wave therefore has approximately 7.07 V RMS. Its peak-to-peak value remains 20 V.\n\nRMS is a different amplitude measure with an equivalent heating interpretation for a resistor under appropriate conditions. The sine-wave conversion factor is not a universal rule for a square wave, pulse train or arbitrary signal.'),
 section('Use precision honestly','The chapter supplies rounded factors 0.707, 1.414 and 2.828. Their products may not return exactly one because they are rounded. Keep adequate precision until the final answer and use an approximation sign when applying these factors.\n\nStart from a known labeled measure, choose the corresponding conversion, then check order: for a nonzero centered sine wave, RMS magnitude is below peak magnitude, and peak-to-peak is twice peak. Source examples with high voltages are paper calculations, not practical measurement instructions.')],
 [mc('A centered sine wave runs from +10 V to −10 V. Its peak-to-peak value is…','20 V',['10 V','0 V','−20 V'],'Peak-to-peak is maximum minus minimum: 10 − (−10) = 20 V.'),
 mc('The same waveform’s peak magnitude is…','10 V',['20 V','−10 V','7.07 V'],'Peak magnitude is the distance from the zero reference to an extreme.'),
 mc('Where is the positive extreme in the source’s standard cycle?','90°',['0°','180°','270°'],'The figure places the positive crest at a quarter cycle.'),
 mc('For a sine wave, RMS from peak is approximately…','0.707 × peak',['2 × peak','1.414 × peak','Peak divided by 2'],'The ideal sinusoidal relationship is peak divided by √2.'),
 mc('A 10 V peak ideal sine wave has RMS near…','7.07 V',['14.14 V','20 V','5 V'],'10/√2 is approximately 7.071 V.'),
 mc('Which order fits a centered nonzero sine wave?','RMS < peak < peak-to-peak',['Peak < RMS < peak-to-peak','Peak-to-peak < peak < RMS','All three are equal'],'The sinusoidal factor is below one, and peak-to-peak is twice peak.'),
 mc('May the 0.707 factor be assumed for any arbitrary waveform?','No; this conversion is sinusoid-specific',['Yes, for every waveform','Only when frequency exceeds 1 kHz','Only when voltage is negative'],'Different waveform shapes have different relationships between peak and RMS.'),
 number('A centered sine wave has 18 V peak-to-peak. Enter its peak magnitude in V.',9,'V','For this waveform, divide peak-to-peak by two.'),
 mc('Why might reverse conversions using 0.707 and 1.414 not recover an exact original value?','The displayed factors are rounded',['The waveform must be unsafe','RMS cannot be reversed','The negative half-cycle is missing'],'Use adequate precision and treat rounded-factor results as approximations.'),
 mc('At 270° in the standard cycle, the instantaneous value is at its…','Negative extreme',['Positive extreme','RMS value','Peak-to-peak value'],'The negative trough is a signed instantaneous value, not a negative peak magnitude.')],
 [sim('Inspect the two extremes','sine','Set peak amplitude to 10 V, then 20 V. Observe the waveform, RMS and peak-to-peak outputs.','Both amplitude measures double when peak doubles','The conversion factors are constant for the ideal sinusoidal shape.'),pick('Choose the amplitude label','A display says 12 V peak-to-peak for a centered sine wave. Which peak belongs to it?','6 V',['12 V','24 V','8.484 V'],'The peak-to-peak span includes both the positive and negative excursions.')],caution='All waveforms here are idealized. The chapter’s higher-voltage examples are paper exercises, not instructions to probe live equipment.',figure='wave')

begin('S8','S2')
add('08 · Move between period and frequency','Use reciprocal relationships and unit conversions to describe how often a waveform repeats and how long one cycle lasts.',
 ['Separate cycles per second from seconds per cycle','Convert ms and kHz before using a reciprocal','Check reciprocal results by multiplication'],[
 section('Two views of one repeating signal','Frequency f counts cycles per second and is measured in hertz. Period T is the time required for one complete cycle and is measured in seconds. A 100 Hz waveform repeats 100 times each second; each cycle therefore occupies 1/100 second.\n\nThe relationships are T = 1/f and f = 1/T. They are reciprocals, not equal numerical quantities. A higher frequency corresponds to a shorter period because more cycles must fit into the same second.'),
 section('Work from milliseconds to hertz','For a hypothetical period of 2 ms, first convert: 2 ms = 0.002 s. Then f = 1/0.002 = 500 Hz. Check by multiplying: 500 cycles/s × 0.002 s/cycle = 1.\n\nEntering 2 into a seconds-based formula would describe a 2-second period and give 0.5 Hz. The missing milli-prefix causes a thousandfold frequency error. Read the time unit before touching the reciprocal key.'),
 section('Work from kilohertz to period','A frequency of 2 kHz is 2,000 Hz. Period is 1/2,000 = 0.0005 s, or 0.5 ms. A useful compatible-unit relation is T in ms = 1/f in kHz, but understand why it works before using it as a shortcut.\n\nIn the widget, raise frequency from 1,000 to 2,000 Hz. The period falls from 1 ms to 0.5 ms. Doubling either quantity halves its reciprocal; it does not make both larger.'),
 section('Report an approximation without rewriting the source','The saved extraction flags the chapter’s display of 1/60 s as 16.6 ms without an approximation sign. The exact reciprocal is a repeating decimal; ordinary rounding to the nearest tenth of a millisecond gives 16.7 ms.\n\nThis lesson identifies 16.6 ms as the source’s approximate displayed value rather than claiming exact equality or nearest-tenth rounding. Keep calculator precision until the last step and label your rounded result appropriately.')],
 [mc('Frequency describes…','Cycles per second',['Seconds per cycle','Volts per cycle','Cycles per volt'],'Hertz measures repetitions per second.'),
 mc('Period describes…','Time for one complete cycle',['Number of cycles in one second','The signal’s peak voltage','Its RMS voltage'],'Period is a duration, measured in seconds.'),
 mc('Which relation obtains frequency from period in seconds?','f = 1/T',['f = T','f = 2T','f = T²'],'Frequency and period are reciprocals.'),
 mc('A 2 ms period corresponds to…','500 Hz',['0.5 Hz','2,000 Hz','500 kHz'],'2 ms is 0.002 s; its reciprocal is 500 Hz.'),
 mc('If frequency doubles, period becomes…','Half as long',['Twice as long','Four times as long','Unchanged'],'The reciprocal relation makes the changes inverse.'),
 mc('What is the period of 2 kHz?','0.5 ms',['2 ms','500 ms','0.5 s'],'1/2,000 s = 0.0005 s = 0.5 ms.'),
 number('A frequency is 100 Hz. Enter its period in ms.',10,'ms','1/100 = 0.01 s, and 0.01 × 1,000 = 10 ms.'),
 mc('Why is treating 2 ms as 2 s wrong?','The time is represented 1,000 times too large',['The two units are equivalent','It only changes the spelling','Frequency does not depend on units'],'Milli means 10⁻³, so the conversion is essential.'),
 mc('Which is the correct nearest-tenth-ms rounding for a 60 Hz period?','16.7 ms',['Exactly 16.6 ms','60 ms','0.0167 ms'],'1/60 s = 16.666… ms, which rounds to 16.7 ms. The source’s 16.6 display is qualified separately.')],
 [sim('Fit more cycles into a second','period','Compare 1,000 Hz and 2,000 Hz. Predict the two periods, then move the control.','1 ms changes to 0.5 ms','Frequency increases while the time occupied by a single cycle decreases.'),pick('Choose the first step','A problem gives T = 5 ms and asks for f in Hz. What should you do first?','Convert 5 ms to 0.005 s',['Use 5 as seconds','Multiply 5 by the voltage','Square 5 ms'],'Compatible units come before the reciprocal: 1/0.005 s = 200 Hz.')],figure='wave')

begin('S10')
add('09 · Separate capacitor charge from energy','Calculate stored charge and stored energy, then predict why voltage changes affect them differently.',
 ['Use Q = CV with capacitance in farads','Use E = ½CV² for electric-field energy','Compare direct and squared voltage scaling'],[
 section('Two quantities are stored, with different units','Capacitance C is measured in farads. Charge Q is measured in coulombs and follows Q = CV. Stored energy E is measured in joules and follows E = 0.5CV² in the accepted capacitor model.\n\nCharge and energy are related, but they are not interchangeable. One says how much charge is associated with the voltage and capacitance; the other measures stored energy. Write the desired quantity and its unit before choosing a formula.'),
 section('Work the charge example from the extraction','The source uses C = 5 µF and V = 12 V. Convert capacitance: 5 µF = 5 × 10⁻⁶ F. Then Q = (5 × 10⁻⁶)(12) = 60 × 10⁻⁶ C = 60 µC.\n\nThe final C is the coulomb unit, not the capacitance variable. The multiplication uses capacitance in farads and voltage in volts. A result of 60 C would ignore the micro-prefix and be one million times too large.'),
 section('Calculate energy independently','Using the clear accepted energy formula with those same values gives E = 0.5 × 5 × 10⁻⁶ × 12². Square voltage first: 12² = 144. Half of 5 × 144 is 360, so E = 360 × 10⁻⁶ J = 360 µJ.\n\nThis is an independently shown teaching calculation from the accepted formula. The extraction flags conflicting right-column source notation that reuses E ambiguously; that expression is not presented as a reliable additional rule.'),
 section('Predict the different scaling','At fixed capacitance, doubling voltage doubles Q = CV but quadruples E = 0.5CV². At fixed voltage, doubling capacitance doubles both. The energy widget displays both quantities so you can compare those effects without confusing their units.\n\nIn the default 100 µF, 5 V example, charge is 500 µC and energy is 1,250 µJ. Increasing voltage to 10 V produces 1,000 µC and 5,000 µJ. These are virtual calculations, not instructions to charge a real capacitor.')],
 [mc('Which formula gives capacitor charge?','Q = CV',['Q = C/V','Q = 0.5CV²','Q = V²/C'],'Charge is directly proportional to capacitance and voltage.'),
 mc('Which unit belongs to charge?','Coulomb',['Farad','Joule','Watt'],'Farad measures capacitance; joule measures energy.'),
 mc('For 5 µF at 12 V, stored charge is…','60 µC',['60 C','360 µJ','2.4 µC'],'(5 × 10⁻⁶ F)(12 V) = 60 × 10⁻⁶ C.'),
 mc('Which accepted formula gives stored energy?','E = 0.5CV²',['E = CV','E = C/V²','E = 2CV'],'Voltage is squared and the one-half factor is retained.'),
 mc('Using 5 µF and 12 V, energy from that formula is…','360 µJ',['60 µJ','720 µJ','360 J'],'0.5 × 5 × 10⁻⁶ × 144 = 360 × 10⁻⁶ J.'),
 mc('At fixed C, doubling V changes Q and E how?','Q doubles; E quadruples',['Both double','Both quadruple','Q quadruples; E doubles'],'Charge depends on V and energy on V².'),
 mc('At fixed V, doubling C changes stored energy how?','It doubles',['It quadruples','It halves','It stays fixed'],'Capacitance appears to the first power in 0.5CV².'),
 number('For 10 µF at 5 V, enter stored charge in µC.',50,'µC','Q = 10 µF × 5 V = 50 µC.'),
 mc('What is wrong with reporting 60 µF as the charge answer?','Farad is a capacitance unit, not a charge unit',['The micro-prefix is forbidden','Charge cannot be calculated','The number must be negative'],'The unit identifies the kind of quantity, independent of its number.'),
 mc('How is the disputed right-column energy notation handled here?','Use the clear accepted formula and label the worked calculation independently',['Treat every E as the same quantity without definition','Copy the ambiguous expression as a second rule','Discard all capacitor mathematics'],'The source discrepancy is disclosed rather than silently treated as verified notation.')],
 [sim('Compare charge and energy responses','energy','Keep C = 100 µF. Compare 5 V with 10 V and watch both outputs.','Charge doubles while energy quadruples','The voltage is squared only in the energy expression.'),pick('Select the squared quantity','Which change gives four times the energy at fixed C?','Double the voltage',['Double the capacitance at fixed voltage','Halve the voltage','Halve the capacitance'],'With capacitance held fixed, 2² produces the fourfold energy factor.')],caution='Stored-energy examples and sliders do not authorize charging or handling physical capacitors. Real stored charge can create hazards.')

begin('S12','S9')
add('10 · Combine capacitances without using the resistor rule','Choose the capacitor series or parallel relationship and use a magnitude check to verify the result.',
 ['Add capacitance directly in parallel','Combine series capacitances by reciprocals','Explain the difference from resistor combinations'],[
 section('Capacitors combine differently from resistors','The accepted chapter relationships give direct addition for parallel capacitance: C_T = C₁ + C₂ + …. Series capacitance uses reciprocal addition: 1/C_T = 1/C₁ + 1/C₂ + ….\n\nDo not transfer the resistor rule solely because the words series and parallel look familiar. The relevant component quantity is different. Decide the component type and its arrangement before selecting a formula.'),
 section('A parallel example','Two 10 µF capacitors in parallel give C_T = 10 + 10 = 20 µF. Keep all values in the same unit while adding. If one value is given in nF and another in µF, convert one before adding their numbers.\n\nThe source material spans pp. 20–21. The saved extraction supports the numerical examples across those pages but does not justify assigning each example to one precise page, so the attribution remains collective.'),
 section('A series example','Three equal 10 µF capacitors in series give C_T = C/n = 10/3 µF ≈ 3.33 µF. For two unequal capacitors, product-over-sum is convenient: C_T = C₁C₂/(C₁ + C₂). For 10 µF and 20 µF, this gives 200/30 ≈ 6.67 µF.\n\nThe shortcut is limited to two series capacitors. For a larger set, add all reciprocals and invert the resulting sum. Rounding too early can spoil the final reciprocal.'),
 section('Check the scale before trusting the display','For at least two positive finite capacitances in series, the equivalent is below the smallest individual capacitance. In parallel, the total exceeds each individual value. Thus the 6.67 µF series result is sensible for 10 and 20 µF, while 30 µF would describe their parallel total.\n\nUse the widget to change one capacitance and compare both arrangements. The total responds continuously, but the series and parallel outputs follow different rules. These are idealized capacitances, without claims about a physical capacitor’s voltage rating or stored-energy safety.')],
 [mc('Two positive capacitances in parallel combine by…','Direct addition',['Subtracting their values','Taking their simple average','Dividing the larger by the smaller'],'The accepted parallel relation is C_T = C₁ + C₂.'),
 mc('Two 10 µF capacitors in parallel give…','20 µF',['5 µF','10 µF','100 µF'],'Parallel capacitances add: 10 + 10 = 20 µF.'),
 mc('Three equal 10 µF capacitors in series give approximately…','3.33 µF',['30 µF','10 µF','0.1 µF'],'For equal series capacitances, C_T = C/n.'),
 mc('Which relation fits two series capacitors?','C₁C₂/(C₁ + C₂)',['C₁ + C₂','C₁ − C₂','C₁C₂ alone'],'The two-term reciprocal sum simplifies to product-over-sum.'),
 mc('A series total for 10 and 20 µF should be…','Less than 10 µF',['More than 20 µF','Exactly 30 µF','Their arithmetic average'],'For two positive finite series capacitances, the total is below the smaller one.'),
 mc('What is approximately 10 µF in series with 20 µF?','6.67 µF',['30 µF','15 µF','200 µF'],'10 × 20/(10 + 20) = 200/30 ≈ 6.67 µF.'),
 number('Enter the parallel total of 4 µF and 6 µF in µF.',10,'µF','Parallel capacitances add: 4 + 6 = 10 µF.'),
 mc('Why can’t you add a bare 500 nF number to a bare 1 µF number?','The numbers use different unit scales',['Capacitances cannot combine','Nanofarads are negative','A reciprocal is always forbidden'],'500 nF = 0.5 µF; compatible units must precede addition.'),
 mc('Which statement correctly compares component rules?','Resistors add in series; capacitors add in parallel',['Both always add in series','Both always add in parallel','Neither can use reciprocals'],'The arrangement words alone do not specify how the component quantity combines.')],
 [sim('Try the same values in both arrangements','capnetwork','Set C₁ = 10 µF and C₂ = 20 µF. Compare the series and parallel results.','Series is about 6.67 µF; parallel is 30 µF','The reciprocal series relationship and direct parallel addition describe different arrangements.'),pick('Catch the swapped rule','A student adds three 10 µF series capacitors to get 30 µF. What is wrong?','The parallel addition rule was used for series',['The correct answer is negative','The capacitors are automatically unequal','Capacitance cannot have a prefix'],'Equal series capacitances divide by the number of capacitors, giving about 3.33 µF.')])

begin('S11','S10')
add('11 · Use a time constant as a timescale','Calculate RC timing and read ideal exponential behavior without mistaking an approximation for exact completion.',
 ['Calculate τ = RC with compatible units','Interpret the accepted one-time-constant charging point','Distinguish approaching a final value from exactly reaching it'],[
 section('Resistance and capacitance set the timescale','The RC time constant is τ = RC, with resistance in ohms and capacitance in farads. Its unit is second. τ tells you the characteristic pace of the change; it is not a fixed stopwatch time at which every change suddenly stops.\n\nAt fixed C, larger R gives a larger time constant. At fixed R, larger C also gives a larger time constant. Doubling both therefore multiplies τ by four, which you can test with the two sliders.'),
 section('Calculate the chapter’s accepted example','For R = 10 kΩ and C = 5 µF, convert R to 10,000 Ω and C to 5 × 10⁻⁶ F. Then τ = 10,000 × 5 × 10⁻⁶ = 0.05 s, or 50 ms.\n\nA compatible shortcut multiplies kΩ by µF to get milliseconds: 10 × 5 = 50 ms. The shortcut works because 10³ × 10⁻⁶ = 10⁻³. Keep that factor visible so you do not mistakenly label 50 as seconds.'),
 section('Understand the one-τ charging point','The accepted source example gives 63.2 V after one charging time constant for a 100 V final level. That is approximately 63.2% of the final level, leaving approximately 36.8% of the difference still to close. It does not mean the capacitor is fully charged.\n\nOur ideal charging graph uses the teaching model fraction = 1 − exp(−t/τ) to represent the exponential behavior. At t = τ, it gives about 0.632. The graph is a calculated model, not a reproduction of the disputed printed labels.'),
 section('Five time constants is close, not exact','In the ideal charging model, five time constants gives approximately 99.3% of the final level. The remaining difference is small but not zero. The response approaches the final level asymptotically rather than becoming mathematically complete at a finite time.\n\nThe saved extraction flags an incorrect-looking discharge percentage, a repeated final time label and an unqualified completion claim in the source figure. Those labels are not adopted here. Use the accepted τ calculation and the explicitly identified ideal charging model instead.'),
 section('Read a changed graph carefully','If τ increases, reaching the same fraction of the final value takes longer. At a fixed elapsed time, the slower charging response has reached a smaller fraction. The widget rescales its time axis with τ, so check the milliseconds shown on that axis rather than comparing curve shapes alone.\n\nThe shape in normalized time remains the same. This separates a response’s exponential shape from its real time duration, and explains why two RC circuits can share the same percentage-at-one-τ rule while changing at different speeds.')],
 [mc('What is the RC time constant?','R × C',['R/C','C/R','R + C'],'Multiply resistance in ohms by capacitance in farads to obtain seconds.'),
 mc('10 kΩ multiplied by 5 µF gives…','50 ms',['50 s','0.05 ms','5 ms'],'10,000 × 5 × 10⁻⁶ = 0.05 s = 50 ms.'),
 mc('At fixed C, doubling R makes τ…','Twice as large',['Half as large','Four times as large','Unchanged'],'τ is directly proportional to R.'),
 mc('Doubling both R and C makes τ…','Four times as large',['Twice as large','Half as large','Unchanged'],'The product receives a factor of 2 × 2 = 4.'),
 mc('At one charging time constant in the accepted ideal example, the level is about…','63.2% of the final value',['100% exactly','36.8% of the final value','0%'],'The remaining difference is about 36.8%, while the level reached is about 63.2%.'),
 mc('For a 100 V final level, the accepted one-τ charging value is…','63.2 V',['100 V','36.8 V','1 V'],'63.2% of 100 V is 63.2 V; this is a mathematical example only.'),
 mc('Does an ideal exponential charging curve reach exactly 100% at five τ?','No; it is close but still below the final value',['Yes, exactly','Only if the capacitance is an integer','Only if resistance is zero'],'The explicit ideal model gives approximately 99.3%, not exact completion.'),
 number('For 20 kΩ and 2 µF, enter τ in ms.',40,'ms','20 × 2 = 40 ms after accounting for kilo × micro = milli.'),
 mc('At the same elapsed time, a larger τ generally means an ideal charging capacitor has reached…','A smaller fraction of its final voltage',['A larger fraction','Exactly the final voltage','A negative capacitance'],'A larger time constant means slower progress through the response.'),
 mc('Why must you inspect the widget’s time-axis labels after changing R or C?','The graph’s displayed time range rescales with τ',['The equation becomes false','The voltage must be physical','The percentage scale is removed'],'The normalized curve shape can look similar even when the duration in ms changes.'),
 mc('Which source item is intentionally not adopted as verified data?','The questionable discharge percentage label',['The accepted RC multiplication','The 10 kΩ and 5 µF values','The one-τ charging example'],'The extraction flags disputed graph labels and completion wording separately.'),
 mc('What units make R × C produce seconds directly?','Ohms and farads',['Kilohms and microfarads without a conversion factor','Ohms and hertz','Volts and amperes'],'Prefixes can be used only when their combined scale is accounted for.')],
 [sim('Move the characteristic time','rc','Set R = 10 kΩ and C = 5 µF. Then double R. Watch τ and the graph’s time labels.','τ changes from 50 ms to 100 ms','The exponential shape in normalized time is unchanged, but the time represented on the axis doubles.'),pick('Interpret the remaining difference','A modeled capacitor reaches 63.2% of its final voltage. About how much of the difference remains?','36.8%',['63.2%','100%','0%'],'The reached fraction and remaining fraction sum to 100%; the process is not complete.'),pick('Choose an honest completion statement','At five τ in the explicit ideal charging model, which wording is best?','Approximately 99.3%, not exactly complete',['Exactly complete for every physical capacitor','Only 63.2%','The response has no defined final level'],'A practical approximation must not be mistaken for a mathematical equality.')],caution='The source’s 100 V values are paper examples. No high-voltage construction, discharge method or handling procedure is authorized here.',figure='wave')

begin('S13','S2')
add('12 · Explore capacitive reactance and lead','Calculate a capacitor’s ideal AC reactance and distinguish its magnitude from its phase relationship.',
 ['Use X_C = 1/(2πfC) with SI values','Predict inverse changes with frequency or capacitance','Read current-leading phase without confusing it with polarity'],[
 section('Reactance is not a resistor value','The capacitor’s ideal capacitive reactance magnitude is X_C = 1/(2πfC), measured in ohms. f is frequency in hertz, C is capacitance in farads, and π is the numerical constant pi.\n\nAlthough X_C shares the ohm unit with resistance, a reactive element’s AC behavior includes phase. Do not treat a reactance label as a statement that the component behaves like an ordinary resistor in every respect.'),
 section('Work through the reciprocal','For a hypothetical f = 1 kHz and C = 1 µF, convert to 1,000 Hz and 1 × 10⁻⁶ F. The denominator is 2π × 1,000 × 10⁻⁶ ≈ 0.006283. Now take its reciprocal: X_C ≈ 159.15 Ω.\n\nStopping at 0.006283 would report the denominator rather than reactance. Enter the entire product inside the denominator, and retain enough precision until the final reciprocal. A calculator’s grouping matters.'),
 section('Predict before moving a control','Frequency and capacitance both appear in the denominator. Doubling either while holding the other fixed halves X_C. Doubling both reduces it to a quarter of its original value.\n\nThe widget uses frequency in kHz and capacitance in nF, with those prefixes converted internally. Read its units before copying a number. Increase frequency at a fixed capacitance and observe the falling reactance curve; then change capacitance and see the curve shift.'),
 section('Current leads voltage in the capacitor figure','The accepted source figure shows capacitor current leading voltage by 90°. A phase lead describes the relative position of repeating waveforms, not a larger amplitude or a physical instruction about which wire carries current first.\n\nThe figure’s current phasor points right and voltage phasor points down under its chosen reference convention. A downward phasor is not a claim that instantaneous voltage is always negative. Keep phase-reference orientation, instantaneous sign and amplitude as separate ideas.')],
 [mc('What is the accepted capacitive-reactance formula?','X_C = 1/(2πfC)',['X_C = 2πfC','X_C = C/f','X_C = f/C'],'The entire frequency-capacitance product is in the denominator.'),
 mc('Which unit belongs to X_C?','Ohm',['Farad','Hertz','Joule'],'Reactance is an opposition-to-AC magnitude expressed in ohms.'),
 mc('At fixed C, doubling frequency makes X_C…','Half as large',['Twice as large','Four times as large','Unchanged'],'Frequency occurs in the denominator.'),
 mc('At fixed f, doubling capacitance makes X_C…','Half as large',['Twice as large','Four times as large','Unchanged'],'Capacitance also occurs in the denominator.'),
 mc('For 1 kHz and 1 µF, X_C is approximately…','159 Ω',['0.00628 Ω','159,000 Ω','6.28 Ω'],'After conversion, take the reciprocal of about 0.006283.'),
 mc('What step is missing if a learner reports the denominator as the answer?','Taking the reciprocal',['Squaring the result','Adding resistance automatically','Converting pi to a prefix'],'The equation starts with 1 divided by the product.'),
 mc('Doubling both f and C gives what reactance factor?','One quarter',['One half','Two','Four'],'The denominator becomes four times as large.'),
 mc('In the accepted capacitor phase figure, which quantity leads?','Current leads voltage',['Voltage leads current','Both peak together under every condition','The figure establishes no phase relation'],'The extraction explicitly identifies a 90° current lead for this figure.'),
 mc('A downward voltage phasor in the chosen reference means…','A relative phase orientation',['Voltage is always negative','Current always flows down a wire','Capacitance is negative'],'Phasor orientation represents phase under a reference convention.'),
 number('At 1 kHz and 1 µF, enter X_C in Ω rounded to two decimals.',159.15,'Ω','1/(2π × 1,000 × 10⁻⁶) ≈ 159.15 Ω.')],
 [sim('Trace the inverse-frequency curve','xc','Keep capacitance at 100 nF. Compare 1 kHz and 2 kHz, then inspect the reactance curve.','Reactance halves','The frequency factor doubles the denominator. The graph is an ideal relationship, not a measured component trace.'),pick('Separate phase from size','Current leading voltage means what?','The current waveform is ahead in phase',['Current must have the larger amplitude','Voltage must always be negative','The capacitor has negative resistance'],'Phase lead describes relative waveform position, independently of amplitude.')],figure='wave')

begin('S14','S15')
add('13 · Combine inductors within a clear model','Interpret inductance and simple combinations while keeping magnetic coupling assumptions visible.',
 ['Read inductance values in H and mH','Apply simple uncoupled combination arithmetic','Recognize where coupling makes the simple model insufficient'],[
 section('Inductance describes opposition to changing current','The chapter identifies inductance as a property opposing changes in current, measured in henrys. L commonly names the inductance. A value of 10 mH is 0.01 H because milli means 10⁻³.\n\nThis description is about current changes. It is not interchangeable with a resistor’s resistance or a capacitor’s capacitance. We keep the property definition separate from the AC reactance calculation introduced in the next lesson.'),
 section('A simple series example','The accepted simple example combines three 4 mH inductors to obtain 12 mH in series. In the explicitly uncoupled widget model, series inductances add just as positive resistances do: L_T = L₁ + L₂.\n\nFor hypothetical 10 mH and 20 mH uncoupled inductors, the series total is 30 mH. The adjective uncoupled is part of the model. You cannot silently discard magnetic interaction for real coils that influence one another.'),
 section('A simple parallel example','The source’s simple equal-value example gives approximately 1.3 mH for three 4 mH inductors in parallel. An equal uncoupled model gives 4/3 ≈ 1.333 mH. The widget uses reciprocal combinations for its explicitly uncoupled two-inductor comparison.\n\nFor 10 and 20 mH in that model, the parallel equivalent is 10 × 20/(10 + 20) ≈ 6.67 mH. These computations illustrate the limited arithmetic model, not a universal formula for magnetically coupled coils.'),
 section('Know where the source is incomplete','The saved extraction notes that reinforcing or opposing magnetic fields affect a mutual-inductance adjustment. It also flags incomplete coupling assumptions and cropped wording in the parallel discussion. We do not reconstruct missing text or infer a general coupled-inductor formula.\n\nBefore using simple addition or reciprocals in a real design, establish whether the uncoupled assumptions apply. For this lesson, the simulator clearly states its assumptions and lets you practice units and arithmetic without pretending that the missing source qualifications have been resolved.')],
 [mc('Inductance is measured in…','Henrys',['Farads','Watts','Coulombs'],'The accepted property definition uses the henry.'),
 mc('Convert 10 mH to H.','0.01 H',['10,000 H','0.1 H','10 H'],'Milli contributes a factor of 10⁻³.'),
 mc('The source’s simple three-4-mH series example gives…','12 mH',['1.33 mH','4 mH','64 mH'],'The accepted simple example adds three 4 mH values.'),
 mc('In the explicitly uncoupled model, 10 and 20 mH in parallel give about…','6.67 mH',['30 mH','15 mH','200 mH'],'Product-over-sum gives 200/30 mH in this limited model.'),
 mc('Which assumption belongs to the widget’s simple combination rules?','Negligible mutual magnetic coupling',['Every physical coil has identical coupling','Inductance is negative','Frequency is a unit of inductance'],'The modeled arithmetic is explicitly limited to uncoupled ideal inductors.'),
 mc('Why is a general coupled-inductor formula not taught from the cropped paragraph?','The needed source qualifications are incomplete',['Coupling never changes anything','Cropped words can be guessed safely','The units table proves the formula'],'Unseen or incompletely specified source material is not evidence for a general rule.'),
 number('In the simple uncoupled series model, enter 8 mH + 12 mH in mH.',20,'mH','Under the stated model, direct addition gives 20 mH.'),
 mc('Which statement preserves the source’s uncertainty?','The simple examples do not establish a universal parallel rule for coupled coils',['All coupled coils use the same reciprocal shortcut','The cropped paragraph has been fully read','Mutual inductance is always zero'],'The accepted simple examples and the unresolved coupling discussion are kept distinct.')],
 [sim('Explore the uncoupled comparison','inductors','Set L₁ = 10 mH and L₂ = 20 mH. Compare the two arrangements, keeping the widget’s uncoupled assumption in view.','Series is 30 mH; parallel is about 6.67 mH','The model excludes mutual magnetic coupling and does not certify a physical coil arrangement.'),pick('Check the model before arithmetic','Two nearby coils influence each other magnetically. What should you establish before applying the widget’s simple rule?','Whether its uncoupled assumption is valid',['That the calculator has four digits','That both values are written in capitals','That the total must equal their product'],'Magnetic interaction can change the applicable model; simple arithmetic alone cannot establish the right assumptions.')])

begin('S14','S13')
add('14 · Compare inductive and capacitive frequency response','Calculate inductive reactance and predict why its frequency trend is opposite to capacitive reactance.',
 ['Use X_L = 2πfL with compatible units','Predict direct changes with frequency and inductance','Keep the qualitative phase lead distinct from reactance magnitude'],[
 section('Read the inductive-reactance equation','The accepted relationship is X_L = 2πfL. X_L is inductive reactance magnitude in ohms, f is frequency in hertz and L is inductance in henrys. Unlike the capacitor equation, the frequency-inductance product is not inside a reciprocal.\n\nThis difference determines the trend: higher frequency gives larger inductive reactance, while higher frequency gives smaller capacitive reactance at fixed capacitance.'),
 section('Work a complete numerical example','For hypothetical f = 1 kHz and L = 10 mH, use 1,000 Hz and 0.01 H. Then X_L = 2π × 1,000 × 0.01 = 20π Ω ≈ 62.83 Ω.\n\nThe prefixes cancel numerically when multiplying kHz by mH, because 10³ × 10⁻³ = 1. That does not mean prefixes can always be ignored; it means this particular compatible product has a net scale factor of one. State that reason if you use the shortcut.'),
 section('Predict proportional changes','Doubling frequency at fixed L doubles X_L. Doubling L at fixed frequency also doubles X_L. Doubling both multiplies reactance by four. Compare those predictions with the rising widget curve.\n\nFor a capacitor, doubling frequency halves X_C instead. The two trends matter when both components appear in a series circuit. Do not subtract their values before checking that they describe the same frequency and are expressed in compatible units.'),
 section('Separate lead from magnitude','The source extraction establishes that voltage leads current in its inductive-reactance discussion. It does not supply a numerical inductive phase angle as accepted evidence, so this lesson keeps the relationship qualitative rather than adding a source-attributed angle.\n\nA statement about which waveform leads does not tell you the total phase of a circuit containing resistance and other reactances. A component’s reactance magnitude, a component phase relationship and complete-circuit impedance are related but separate ideas.')],
 [mc('Which equation gives ideal inductive reactance magnitude?','X_L = 2πfL',['X_L = 1/(2πfL)','X_L = L/f','X_L = f/L'],'Inductive reactance uses a direct frequency-inductance product.'),
 mc('What unit is used for L in the base-unit calculation?','Henry',['Farad','Hertz','Ohm'],'Inductance is expressed in henrys.'),
 mc('For 1 kHz and 10 mH, X_L is approximately…','62.83 Ω',['0.06283 Ω','6,283 Ω','159.15 Ω'],'2π × 1,000 × 0.01 = 20π Ω.'),
 mc('At fixed L, doubling frequency makes X_L…','Twice as large',['Half as large','Unchanged','Zero'],'Frequency appears to the first power in the product.'),
 mc('Doubling both f and L makes X_L…','Four times as large',['Twice as large','One quarter','Unchanged'],'The two factors each double, giving 2 × 2 = 4.'),
 mc('At fixed component values, what does increasing frequency do?','X_L rises while X_C falls',['Both rise','Both fall','Both stay fixed'],'The inductor uses a product; the capacitor uses a reciprocal.'),
 mc('Why can kHz times mH be used numerically in this formula?','The kilo and milli factors multiply to one',['Every prefix may be omitted','Both units become watts','The formula contains a reciprocal'],'10³ × 10⁻³ = 1, after explicitly accounting for the scales.'),
 mc('Which phase relation is accepted qualitatively for the inductor discussion?','Voltage leads current',['Current leads voltage','Phase means a larger amplitude only','The source establishes equal instantaneous values at all times'],'The extraction supports a qualitative voltage lead; no additional numerical angle is attributed here.'),
 number('At 2 kHz and 10 mH, enter X_L in Ω rounded to two decimals.',125.66,'Ω','2π × 2,000 × 0.01 ≈ 125.66 Ω.'),
 mc('Does an inductor’s reactance alone define the total phase of every RLC circuit?','No; the complete circuit must be considered',['Yes, in every topology','Only if the unit is capitalized','Only if current is positive'],'Other components and their arrangement affect complete-circuit impedance and phase.')],
 [sim('Trace the rising frequency curve','xl','Keep L = 10 mH. Compare 1 and 2 kHz, then raise inductance at fixed frequency.','Doubling either factor doubles X_L','The plot and calculated value follow the direct product 2πfL.'),sim('Compare the opposite trend','xc','In this separate capacitor widget, hold C = 100 nF and increase frequency from 1 to 2 kHz.','X_C halves rather than doubles','The comparison isolates the opposite frequency trends of ideal inductive and capacitive reactance.'),pick('Choose the right trend','Which component’s ideal reactance grows when frequency grows at fixed component value?','Inductor',['Capacitor','Both decrease','Neither depends on frequency'],'X_L = 2πfL grows with f, whereas X_C = 1/(2πfC) decreases.')],figure='wave')

begin('S16','S13','S14')
add('15 · Combine a series circuit’s resistance and reactance','Use a defined signed reactive difference and a nonnegative magnitude, without extending a series formula to unrelated parallel networks.',
 ['Identify inductive versus capacitive predominance','Calculate series impedance magnitude','Keep a magnitude separate from a signed reactive difference'],[
 section('Define the reactive difference before squaring','For this series model, define X_net = X_L − X_C. A positive difference is inductive and a negative one is capacitive. The magnitude relationship is |Z| = √(R² + X_net²).\n\nThe printed source example writes the difference in the opposite order before squaring. Either order gives the same magnitude because the square removes the sign, but it does not mean the sign is irrelevant to interpreting predominance. We state our convention explicitly.'),
 section('Work the accepted 3–4–5 example','The source gives R = 3 Ω, X_L = 16 Ω and X_C = 20 Ω. Our signed difference is 16 − 20 = −4 Ω, so the circuit is predominantly capacitive. The magnitude is √(3² + (−4)²) = √(9 + 16) = √25 = 5 Ω.\n\nDo not add 3 + 16 + 20 to obtain 39 Ω. Reactive contributions oppose one another here, and resistance combines with the net reactive contribution through the magnitude relation rather than direct arithmetic addition.'),
 section('The square does not make the physical interpretation disappear','A magnitude cannot be negative. A net reactance of −4 Ω and one of +4 Ω at the same R give the same numerical magnitude, but different predominance. If X_L = X_C, the net reactive difference is zero and the magnitude equals R in this ideal series model.\n\nThe accepted source phasor sketch labels its example capacitive. We do not add an unsupported total circuit phase angle or use the magnitude formula to claim the current is leading by a particular numerical angle.'),
 section('Use the widget’s quantities correctly','The simulator takes frequency, L, C and R, then calculates X_L, X_C and |Z|. It is not asking you to enter reactance values into an inductance or capacitance field. Watch the units and distinguish the inputs from the derived outputs.\n\nWith frequency, L and R fixed, increasing C lowers X_C. The complete impedance may decrease toward cancellation and then increase beyond it; do not claim that every capacitance increase always lowers |Z|. Compare the changing difference, not just one component in isolation.'),
 section('Respect topology and source limits','This formula is for the stated ideal series RLC model. The extraction flags ambiguous parallel-impedance wording and does not support generalizing that expression to arbitrary parallel RLC networks. Those details are not reconstructed here.\n\nA reliable answer names the arrangement, keeps all reactance values at the same frequency, defines its signed difference, performs the square and square root carefully, and reports a nonnegative magnitude with the ohm unit.')],
 [mc('For R = 3 Ω, X_L = 16 Ω and X_C = 20 Ω, our X_net is…','−4 Ω',['+4 Ω','36 Ω','39 Ω'],'The stated convention is X_L − X_C = 16 − 20.'),
 mc('That signed difference indicates which predominance?','Capacitive',['Inductive','Purely resistive despite unequal reactances','A negative resistance'],'Capacitive reactance magnitude is larger in the accepted source example.'),
 mc('What is the impedance magnitude of the accepted example?','5 Ω',['39 Ω','−5 Ω','4 Ω'],'√(3² + (−4)²) = √25 = 5 Ω.'),
 mc('What operation is required after adding the two squared terms?','Take the square root',['Take the reciprocal automatically','Add X_L again','Keep the result in squared ohms'],'The formula is a square root of the sum, not the sum itself.'),
 mc('Why do +4 Ω and −4 Ω give the same magnitude term when squared?','Both squares are 16 Ω²',['Their predominance is identical','Both are zero','Resistance disappears'],'The magnitude calculation loses sign, while the separately defined sign retains interpretation.'),
 mc('If X_L = X_C in this ideal series model, |Z| equals…','R',['Zero for every R','X_L + X_C','R² without a square root'],'The net reactive difference becomes zero.'),
 mc('Can this series relation be applied to any arbitrary parallel RLC network?','No; topology and the appropriate model matter',['Yes, always','Only if the values are rounded','Only if all prefixes are milli'],'The accepted evidence supports a series model, not a universal parallel formula.'),
 number('For R = 6 Ω and a net reactance magnitude of 8 Ω, enter |Z| in Ω.',10,'Ω','√(6² + 8²) = √100 = 10 Ω.'),
 mc('The widget’s L field expects…','Inductance in its labeled unit',['A reactance value in ohms','Impedance magnitude','A phase angle'],'The simulator derives reactance from frequency and component values.'),
 mc('Which statement about increasing C is safe for the whole series circuit?','Watch cancellation; |Z| need not decrease for every increase',['It always doubles |Z|','It always lowers |Z| without limit','It cannot affect X_C'],'X_C falls, but the net reactive difference may pass through zero and grow again.'),
 mc('What is wrong with reporting an impedance magnitude of −5 Ω?','A magnitude must be nonnegative',['Its unit must be hertz','Every capacitance is negative','The source allows negative magnitudes'],'The signed reactive difference and nonnegative magnitude have different roles.'),
 mc('What should be shared when comparing X_L and X_C in one circuit calculation?','The operating frequency and compatible units',['Only their written letter size','Only the number of decimal digits','No common conditions are needed'],'Both reactances describe the same operating condition in this model.')],
 [sim('Watch reactive cancellation','rlc','Hold frequency, L and R fixed while changing C. Compare X_L, X_C and |Z| rather than assuming a permanent trend.','The magnitude follows the size of the net reactive difference','Resistance and reactive difference combine by the square-root relation in this series model.'),pick('Preserve the sign information','Which label belongs to X_L = 16 Ω and X_C = 20 Ω under X_net = X_L − X_C?','Capacitive predominance with X_net = −4 Ω',['Inductive predominance with X_net = −4 Ω','Negative impedance magnitude','No reactive contribution'],'The sign identifies predominance; the magnitude calculation then squares the difference.'),pick('Choose the magnitude route','After obtaining 9 + 16 = 25 Ω² in the source example, what comes next?','√25 = 5 Ω',['25 Ω is already the impedance','1/25 Ω','25 + 20 Ω'],'The square root restores the ohm unit and gives the magnitude.')],figure='circuit')

begin('S17','S13','S14')
add('16 · Find and check a resonant frequency','Calculate ideal LC resonance and verify it by comparing inductive and capacitive reactance at the same frequency.',
 ['Convert µH and pF before multiplying','Use f_r = 1/(2π√(LC))','Check resonance by matching reactance magnitudes'],[
 section('Resonance starts with a matching condition','The accepted chapter relationship sets X_L = X_C. Substituting their formulas gives 2πfL = 1/(2πfC). Solving that relation gives f_r = 1/(2π√(LC)), with L in henrys, C in farads and frequency in hertz.\n\nThis lesson uses the source’s explicitly series example and the ideal model. It does not adopt the source’s ambiguous maximum-current wording as a general statement about every series and parallel resonant circuit.'),
 section('Keep both prefixes visible','The source example uses 200 µH and 200 pF. Convert them independently: 200 µH = 2 × 10⁻⁴ H and 200 pF = 2 × 10⁻¹⁰ F. Their product is 4 × 10⁻¹⁴ H·F.\n\nTaking the square root gives 2 × 10⁻⁷ s. The exponent is halved under the square root; the leading 4 becomes 2. Confusing pico with micro changes the capacitance by a millionfold factor, and the square root turns that into a thousandfold frequency error.'),
 section('Finish the calculation before rounding','The denominator is 2π × 2 × 10⁻⁷ s ≈ 1.256637 × 10⁻⁶ s. Its reciprocal is approximately 795,775 Hz, or 795.8 kHz. The source reports approximately 795 kHz; we distinguish that display from our more precise independent recalculation.\n\nKeep the whole LC product inside the square root, and the whole 2π√(LC) product inside the reciprocal. Leaving out either the square root or reciprocal produces a very different kind of calculation.'),
 section('Check the condition using a second route','At about 795.8 kHz with those component values, X_L = 2πfL is about 1,000 Ω. Calculating X_C = 1/(2πfC) gives about the same 1,000 Ω. Agreement checks the resonance calculation using the underlying condition.\n\nIn the ideal series RLC model, cancellation of equal reactance magnitudes leaves the resistance in the impedance magnitude. It does not imply every real resonant circuit has zero impedance, or that component tolerances and losses disappear.'),
 section('Predict a component change','Because frequency is inversely proportional to √(LC), quadrupling C while holding L fixed halves f_r. Doubling C reduces f_r by a factor of √2, not by a factor of two. The same statements apply to changing L while holding C fixed.\n\nUse the resonance widget to test the difference between a twofold and fourfold change. Read the component units before comparing examples. The goal is to combine prefix handling, square roots, reciprocals and a physical condition into one dependable chain of reasoning.')],
 [mc('What equality identifies the accepted ideal resonance condition?','X_L = X_C',['R = 0 in every circuit','L = C numerically','V = I numerically'],'The inductive and capacitive reactance magnitudes match.'),
 mc('What is the accepted resonance-frequency formula?','1/(2π√(LC))',['2πLC','1/(LC)','√(L/C)'],'The complete LC product is under a square root, and the resulting denominator is inverted.'),
 mc('Convert 200 pF to F.','2 × 10⁻¹⁰ F',['2 × 10⁻⁴ F','2 × 10⁻⁶ F','200 F'],'Pico means 10⁻¹²: 200 × 10⁻¹² = 2 × 10⁻¹⁰.'),
 mc('What is the product of 2 × 10⁻⁴ H and 2 × 10⁻¹⁰ F?','4 × 10⁻¹⁴ H·F',['4 × 10⁻⁴⁰ H·F','4 × 10⁻⁶ H·F','2 × 10⁻¹⁴ H·F'],'Multiply the leading numbers and add exponents.'),
 mc('What is √(4 × 10⁻¹⁴)?','2 × 10⁻⁷',['2 × 10⁻¹⁴','4 × 10⁻⁷','2 × 10⁻²⁸'],'The square root of 4 is 2 and half of −14 is −7.'),
 mc('The independently recalculated frequency for 200 µH and 200 pF is near…','795.8 kHz',['795.8 Hz','0.7958 Hz','7.958 MHz'],'The complete reciprocal is about 795,775 Hz, converted to kHz.'),
 mc('At fixed L, quadrupling C makes resonant frequency…','Half as large',['One quarter','Twice as large','Unchanged'],'√4 = 2 appears in the denominator.'),
 mc('At fixed L, doubling C makes resonant frequency…','Smaller by a factor of √2',['Half as large exactly','Twice as large','Unchanged'],'The square root makes the scaling different from a simple inverse-C relationship.'),
 mc('Which independent check supports the resonance answer?','Calculate X_L and X_C at the proposed f and compare them',['Check whether L and C have the same bare number','Ignore all prefixes','Set every resistance to zero without qualification'],'The check returns to the accepted matching condition.'),
 mc('What is intentionally not generalized from the ambiguous source prose?','A maximum-current claim for every resonant topology',['The accepted frequency formula','The need for compatible units','The equality of ideal reactance magnitudes'],'Series and parallel conditions must not be collapsed into one unsupported blanket claim.')],
 [sim('Compare square-root scaling','resonance','Keep L = 200 µH. Compare C = 200 pF and C = 800 pF, which is four times as large.','Frequency halves from about 795.8 kHz to 397.9 kHz','The capacitance multiplier of four becomes a denominator multiplier of two under the square root.'),pick('Choose the independent check','You have a proposed resonant frequency. What should you compare at that same frequency?','Inductive and capacitive reactance magnitudes',['Capacitance in pF and inductance in µH as bare numbers','Only the supply voltage','Only the number of decimal places'],'Using the same frequency and proper units should make X_L and X_C approximately equal.'),pick('Diagnose a prefix error','A learner substitutes 200 µF where the source gives 200 pF. What changed?','The represented capacitance became one million times larger',['The units remained equivalent','Only a letter style changed','Inductance doubled'],'Micro and pico differ by six powers of ten; the resulting frequency would be a thousand times smaller in the ideal formula.')],figure='wave')

